begin();o.items.forEach((i,n)=>{const name=wrapText(i.name,217,9,true),brand=wrapText(i.brand,217,8),color=wrapText(i.color==='Lainnya'?i.customColor:i.color,75,9),h=Math.max(48,(name.length+brand.length)*13+18,color.length*13+18);if(y+h>732)begin();if(n%2===0)rect(34,y,527,h,'#f4f8fc');text(n+1,44,y+19,9);name.forEach((s,k)=>text(s,74,y+18+k*13,9,true));brand.forEach((s,k)=>text(s,74,y+18+(name.length+k)*13,8,false,muted));color.forEach((s,k)=>text(s,303,y+18+k*13,9));text(i.qty,394,y+19,9,true);if(o.showPrice){const price=i.price===''?'-':fmt(i.price),subtotal=i.price===''?'-':fmt(i.qty*i.price),ps=Math.min(8,66*8/textWidth(price,8)),ss=Math.min(8,66*8/textWidth(subtotal,8,true));text(price,490-textWidth(price,ps),y+19,ps);text(subtotal,550-textWidth(subtotal,ss,true),y+19,ss,true);}y+=h;line(34,y,527);});
